// Two variable definitions

// Data for buffer
const concwa1 = [1.25, 1.3, 1.35, 1.4, 1.45, 1.5, 1.55, 1.6, 1.65, 1.7, 1.75];
const volwa1 = [225, 230, 235, 240, 245, 250, 255, 260, 265, 270, 275];
const voltot1 = [800, 825, 850, 900, 925, 950, 975];
const masscb1 = OLI.random(75, 95, 2); 
const c1 = OLI.random(0,10);1
const v1 = OLI.random(0,10);
const v0 = OLI.random(0,6);
const concwa = concwa1[c1] .toPrecision(3); 
const volwa = volwa1[v1] .toPrecision(3); 
const volbuff = voltot1[v0] .toPrecision(3); 
const molwa1 = (concwa* volwa/1000) .toPrecision(3); 
const molcb1 = (masscb1/135.00) .toPrecision(4); 

// pH of buffer
const ka = 2.8e-9; 
const pka = -Math.log10(ka);
const molratio1 = molcb1/molwa1;
const hhratio1 = Math.log10(molratio1); 
const ph1 = (pka + hhratio1) .toPrecision(3); 
const ph1low = 0.98*ph1; 
const ph1high = 1.02*ph1;

// Data for addition of strong acid or strong base
const voladd = [10, 12, 14, 16, 18, 20]; 
const concadd = [2, 2.1, 2.2, 2.3, 2.4, 2.5]; 
const voltotadd = [350, 355, 360, 365, 370, 375, 380, 385, 390, 395, 400];
const v2 = OLI.random(0,5);
const c2 = OLI.random(0,5);
const v3 = OLI.random(0,5);
const c3 = OLI.random(0,5);
const v4 = OLI.random(0,10);
const v5 = OLI.random(0,10);
const volsa = voladd[v2] .toPrecision(3);
const concsa = concadd[c2] .toPrecision(3);
const voltot2 = voltotadd[v4] .toPrecision(3);
const volsb = voladd[v3] .toPrecision(3);
const concsb = concadd [c3] .toPrecision(3);
const voltot3 = voltotadd[v5] .toPrecision(3);

const molsa = volsa*concsa/1000;
const molsb = volsb*concsb/1000;
const molsasf = molsa .toPrecision(3);
const molsbsf = molsb .toPrecision(3);

// pH after adding strong acid
const molwa2 = molwa1*voltot2/volbuff;
const molcb2 = molcb1*voltot2/volbuff;
const molacid2 = molwa2+molsa;
const molbase2 = molcb2-molsa;
const molwa2sf = molwa2 .toPrecision(3);
const molcb2sf = molcb2 .toPrecision(3);
const molacid2sf = molacid2 .toPrecision(3);
const molbase2sf = molbase2 .toPrecision(3);
const molratio2 = molbase2/molacid2;
const hhratio2 = Math.log10(molratio2);
const ph2 = (pka + hhratio2) .toPrecision(3);
const ph2low = 0.98*ph2;
const ph2high = 1.02*ph2;

//pH after adding strong base
const molwa3 = molwa1* voltot3/volbuff;
const molcb3 = molcb1* voltot3/volbuff;
const molacid3 = molwa3-molsb;
const molbase3 = molcb3+molsb;
const molwa3sf = molwa3 .toPrecision(3);
const molcb3sf = molcb3 .toPrecision(3);
const molacid3sf = molacid3 .toPrecision(3);
const molbase3sf = molbase3 .toPrecision(3);
const molratio3 = molbase3/molacid3;
const hhratio3 = Math.log10(molratio3);
const ph3 = (pka + hhratio3) .toPrecision(3);
const ph3low = 0.98*ph3;
const ph3high = 1.02*ph3;

// Expose variables to OLI
module.exports = {
  concwa, volwa, masscb1, volbuff, molwa1, molcb1, ka, pka, molratio1, hhratio1, ph1, ph1low, ph1high, volsa, concsa, voltot2, volsb, concsb, voltot3, molsa, molsb, molsasf, molsbsf, molwa2, molcb2, molacid2, molbase2, molwa2sf, molcb2sf, molacid2sf, molbase2sf, molratio2, hhratio2, ph2, ph2low, ph2high, molwa3, molcb3, molacid3, molbase3, molwa3sf, molcb3sf, molacid3sf, molbase3sf, molratio3, hhratio3, ph3, ph3low, ph3high,  
  };
